{"version":3,"file":"tagify.js","sources":["src/parts/constants.js","src/parts/helpers.js","src/parts/defaults.js","src/parts/suggestions.js","src/parts/dropdown.js","src/parts/persist.js","src/parts/texts.js","src/parts/templates.js","src/parts/EventDispatcher.js","src/parts/events.js","src/tagify.js"],"sourcesContent":["export var ZERO_WIDTH_CHAR = '\\u200B';","import {ZERO_WIDTH_CHAR} from './constants'\r\n\r\n// console.json = console.json || function(argument){\r\n//     for(var arg=0; arg < arguments.length; ++arg)\r\n//         console.log(  JSON.stringify(arguments[arg], null, 4)  )\r\n// }\r\n\r\n// const isEdge = /Edge/.test(navigator.userAgent)\r\nexport const sameStr = (s1, s2, caseSensitive, trim) => {\r\n    // cast to String\r\n    s1 = \"\"+s1;\r\n    s2 = \"\"+s2;\r\n\r\n    if( trim ){\r\n        s1 = s1.trim()\r\n        s2 = s2.trim()\r\n    }\r\n\r\n    return caseSensitive\r\n        ? s1 == s2\r\n        : s1.toLowerCase() == s2.toLowerCase()\r\n}\r\n\r\n\r\n// const getUID = () => (new Date().getTime() + Math.floor((Math.random()*10000)+1)).toString(16)\r\nexport const removeCollectionProp = (collection, unwantedProps) => collection && Array.isArray(collection) && collection.map(v => omit(v, unwantedProps))\r\n\r\nexport function omit(obj, props){\r\n    var newObj = {}, p;\r\n    for( p in obj )\r\n        if( props.indexOf(p) < 0 )\r\n            newObj[p] = obj[p]\r\n    return newObj\r\n}\r\n\r\nexport function decode( s ) {\r\n    var el = document.createElement('div');\r\n    return s.replace(/\\&#?[0-9a-z]+;/gi, function(enc){\r\n        el.innerHTML = enc;\r\n        return el.innerText\r\n    })\r\n}\r\n\r\n/**\r\n * utility method\r\n * https://stackoverflow.com/a/35385518/104380\r\n * @param  {String} s [HTML string]\r\n * @return {Object}   [DOM node]\r\n */\r\nexport function parseHTML( s ){\r\n    var parser = new DOMParser(),\r\n        node   = parser.parseFromString(s.trim(), \"text/html\");\r\n\r\n    return node.body.firstElementChild;\r\n}\r\n\r\n/**\r\n * Removed new lines and irrelevant spaces which might affect layout, and are better gone\r\n * @param {string} s [HTML string]\r\n */\r\nexport function minify( s ){\r\n    return s ? s\r\n        .replace(/\\>[\\r\\n ]+\\</g, \"><\")\r\n        .split(/>\\s+</).join('><').trim()\r\n        : \"\"\r\n}\r\n\r\nexport function removeTextChildNodes( elm ){\r\n    var iter = document.createNodeIterator(elm, NodeFilter.SHOW_TEXT, null, false),\r\n        textnode;\r\n\r\n    // print all text nodes\r\n    while (textnode = iter.nextNode()){\r\n        if( !textnode.textContent.trim() )\r\n            textnode.parentNode.removeChild(textnode)\r\n    }\r\n}\r\n\r\nexport function getfirstTextNode( elm, action ){\r\n    action = action || 'previous';\r\n    while ( elm = elm[action + 'Sibling'] )\r\n        if( elm.nodeType == 3 )\r\n            return elm\r\n}\r\n\r\n/**\r\n * utility method\r\n * https://stackoverflow.com/a/6234804/104380\r\n */\r\nexport function escapeHTML( s ){\r\n    return typeof s == 'string' ? s\r\n        .replace(/&/g, \"&amp;\")\r\n        .replace(/</g, \"&lt;\")\r\n        .replace(/>/g, \"&gt;\")\r\n        .replace(/\"/g, \"&quot;\")\r\n        .replace(/`|'/g, \"&#039;\")\r\n        : s;\r\n}\r\n\r\n/**\r\n * Checks if an argument is a javascript Object\r\n */\r\nexport function isObject(obj) {\r\n    var type = Object.prototype.toString.call(obj).split(' ')[1].slice(0, -1);\r\n    return obj === Object(obj) && type != 'Array' && type != 'Function' && type != 'RegExp' && type != 'HTMLUnknownElement';\r\n}\r\n\r\n/**\r\n * merge objects into a single new one\r\n * TEST: extend({}, {a:{foo:1}, b:[]}, {a:{bar:2}, b:[1], c:()=>{}})\r\n */\r\nexport function extend( o, o1, o2) {\r\n    if( !(o instanceof Object) ) o = {};\r\n\r\n    copy(o, o1);\r\n    if( o2 )\r\n        copy(o, o2)\r\n\r\n    function copy(a,b){\r\n        // copy o2 to o\r\n        for( var key in b )\r\n            if( b.hasOwnProperty(key) ){\r\n                if( isObject(b[key]) ){\r\n                    if( !isObject(a[key]) )\r\n                        a[key] = Object.assign({}, b[key])\r\n                    else\r\n                        copy(a[key], b[key])\r\n\r\n                    continue;\r\n                }\r\n\r\n                if( Array.isArray(b[key]) ){\r\n                    a[key] = Object.assign([], b[key])\r\n                    continue\r\n                }\r\n\r\n                a[key] = b[key]\r\n            }\r\n    }\r\n\r\n    return o\r\n}\r\n\r\n/**\r\n * concatenates N arrays without dups.\r\n * If an array's item is an Object, compare by `value`\r\n */\r\nexport function concatWithoutDups(){\r\n    const newArr = [],\r\n        existingObj = {};\r\n\r\n    for( let arr of arguments ) {\r\n        for( let item of arr ) {\r\n            // if current item is an object which has yet to be added to the new array\r\n            if( isObject(item) ){\r\n                if( !existingObj[item.value] ){\r\n                    newArr.push(item)\r\n                    existingObj[item.value] = 1\r\n                }\r\n            }\r\n\r\n            // if current item is not an object and is not in the new array\r\n            else if( !newArr.includes(item) )\r\n                newArr.push(item)\r\n        }\r\n    }\r\n\r\n    return newArr\r\n}\r\n\r\n/**\r\n *  Extracted from: https://stackoverflow.com/a/37511463/104380\r\n * @param {String} s\r\n */\r\nexport function unaccent( s ){\r\n    // if not supported, do not continue.\r\n    // developers should use a polyfill:\r\n    // https://github.com/walling/unorm\r\n    if( !String.prototype.normalize )\r\n        return s\r\n\r\n    if (typeof(s) === 'string')\r\n        return s.normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g, \"\")\r\n}\r\n\r\n/**\r\n * Meassures an element's height, which might yet have been added DOM\r\n * https://stackoverflow.com/q/5944038/104380\r\n * @param {DOM} node\r\n */\r\nexport function getNodeHeight( node ){\r\n    var height, clone = node.cloneNode(true)\r\n    clone.style.cssText = \"position:fixed; top:-9999px; opacity:0\"\r\n    document.body.appendChild(clone)\r\n    height = clone.clientHeight\r\n    clone.parentNode.removeChild(clone)\r\n    return height\r\n}\r\n\r\nexport var isChromeAndroidBrowser = () => /(?=.*chrome)(?=.*android)/i.test(navigator.userAgent)\r\n\r\nexport function getUID() {\r\n    return ([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g, c =>\r\n        (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16)\r\n    )\r\n}\r\n\r\nexport function isNodeTag(node){\r\n    return node && node.classList && node.classList.contains(this.settings.classNames.tag)\r\n}\r\n\r\n/**\r\n* Get the caret position relative to the viewport\r\n* https://stackoverflow.com/q/58985076/104380\r\n*\r\n* @returns {object} left, top distance in pixels\r\n*/\r\nexport function getCaretGlobalPosition(){\r\n   const sel = document.getSelection()\r\n\r\n   if( sel.rangeCount ){\r\n       const r = sel.getRangeAt(0)\r\n       const node = r.startContainer\r\n       const offset = r.startOffset\r\n       let rect,  r2;\r\n\r\n       if (offset > 0) {\r\n           r2 = document.createRange()\r\n           r2.setStart(node, offset - 1)\r\n           r2.setEnd(node, offset)\r\n           rect = r2.getBoundingClientRect()\r\n           return {left:rect.right, top:rect.top, bottom:rect.bottom}\r\n       }\r\n\r\n       if( node.getBoundingClientRect )\r\n           return node.getBoundingClientRect()\r\n   }\r\n\r\n   return {left:-9999, top:-9999}\r\n}\r\n\r\n/**\r\n * Injects content (either string or node) at the current the current (or specificed) caret position\r\n * @param {content} string/node\r\n * @param {range} Object (optional, a range other than the current window selection)\r\n */\r\nexport function injectAtCaret(content, range){\r\n    var selection = window.getSelection();\r\n    range = range || selection.getRangeAt(0)\r\n\r\n    if( typeof content == 'string' )\r\n        content = document.createTextNode(content)\r\n\r\n    if( range ) {\r\n        range.deleteContents()\r\n        range.insertNode(content)\r\n    }\r\n\r\n    return content\r\n}\r\n\r\n/** Setter/Getter\r\n * Each tag DOM node contains a custom property called \"__tagifyTagData\" which hosts its data\r\n * @param {Node}   tagElm\r\n * @param {Object} data\r\n */\r\nexport function getSetTagData(tagElm, data, override){\r\n    if( !tagElm ){\r\n        Tagify.logger.warn(\"tag element doesn't exist\",{tagElm, data})\r\n        return data\r\n    }\r\n\r\n    if( data )\r\n        tagElm.__tagifyTagData = override\r\n            ? data\r\n            : extend({}, tagElm.__tagifyTagData || {}, data)\r\n\r\n    return tagElm.__tagifyTagData\r\n}\r\n\r\nexport function placeCaretAfterNode( node ){\r\n    if( !node || !node.parentNode ) return\r\n\r\n    var nextSibling = node,\r\n        sel = window.getSelection(),\r\n        range = sel.getRangeAt(0);\r\n\r\n    if (sel.rangeCount) {\r\n        range.setStartAfter(nextSibling);\r\n        range.collapse(true)\r\n        // range.setEndBefore(nextSibling || node);\r\n        sel.removeAllRanges();\r\n        sel.addRange(range);\r\n    }\r\n}\r\n\r\n/**\r\n * iterate all tags, checking if multiple ones are close-siblings and if so, add a zero-space width character between them,\r\n * which forces the caret to be rendered when the selection is between tags.\r\n * Also do that if the tag is the first node.\r\n * @param {Array} tags\r\n */\r\nexport function fixCaretBetweenTags(tags, TagifyHasFocuse) {\r\n    tags.forEach(tag => {\r\n        if( getSetTagData(tag.previousSibling) || !tag.previousSibling ) {\r\n            var textNode = document.createTextNode(ZERO_WIDTH_CHAR)\r\n            tag.before(textNode)\r\n            TagifyHasFocuse && placeCaretAfterNode(textNode)\r\n        }\r\n    })\r\n}\r\n","export default {\r\n    delimiters          : \",\",            // [RegEx] split tags by any of these delimiters (\"null\" to cancel) Example: \",| |.\"\r\n    pattern             : null,           // RegEx pattern to validate input by. Ex: /[1-9]/\r\n    tagTextProp         : 'value',        // tag data Object property which will be displayed as the tag's text\r\n    maxTags             : Infinity,       // Maximum number of tags\r\n    callbacks           : {},             // Exposed callbacks object to be triggered on certain events\r\n    addTagOnBlur        : true,           // automatically adds the text which was inputed as a tag when blur event happens\r\n    addTagOn            : ['blur', 'tab', 'enter'],  // if the tagify field (in a normal mode) has any non-tag input in it, convert it to a tag on any of these events: blur away from the field, click \"tab\"/\"enter\" key\r\n    onChangeAfterBlur   : true,           // By default, the native way of inputs' onChange events is kept, and it only fires when the field is blured.\r\n    duplicates          : false,          // \"true\" - allow duplicate tags\r\n    whitelist           : [],             // Array of tags to suggest as the user types (can be used along with \"enforceWhitelist\" setting)\r\n    blacklist           : [],             // A list of non-allowed tags\r\n    enforceWhitelist    : false,          // Only allow tags from the whitelist\r\n    userInput           : true,           // disable manually typing/pasting/editing tags (tags may only be added from the whitelist)\r\n    keepInvalidTags     : false,          // if true, do not remove tags which did not pass validation\r\n    createInvalidTags   : true,           // if false, do not create invalid tags from invalid user input\r\n    mixTagsAllowedAfter : /,|\\.|\\:|\\s/,   // RegEx - Define conditions in which mix-tags content allows a tag to be added after\r\n    mixTagsInterpolator : ['[[', ']]'],   // Interpolation for mix mode. Everything between these will become a tag, if is a valid Object\r\n    backspace           : true,           // false / true / \"edit\"\r\n    skipInvalid         : false,          // If `true`, do not add invalid, temporary, tags before automatically removing them\r\n    pasteAsTags         : true,           // automatically converts pasted text into tags. if \"false\", allows for further text editing\r\n\r\n    editTags            : {\r\n        clicks      : 2,                  // clicks to enter \"edit-mode\": 1 for single click. any other value is considered as double-click\r\n        keepInvalid : true                // keeps invalid edits as-is until `esc` is pressed while in focus\r\n    },              // 1 or 2 clicks to edit a tag. false/null for not allowing editing\r\n    transformTag        : ()=>{},         // Takes a tag input string as argument and returns a transformed value\r\n    trim                : true,           // whether or not the value provided should be trimmed, before being added as a tag\r\n    a11y: {\r\n        focusableTags: false\r\n    },\r\n\r\n    mixMode: {\r\n        insertAfterTag  : '\\u00A0',       // String/Node to inject after a tag has been added (see #588)\r\n    },\r\n\r\n    autoComplete: {\r\n        enabled: true,        // Tries to suggest the input's value while typing (match from whitelist) by adding the rest of term as grayed-out text\r\n        rightKey: false,      // If `true`, when Right key is pressed, use the suggested value to create a tag, else just auto-completes the input. in mixed-mode this is set to \"true\"\r\n        tabKey: false,        // If 'true`, pressing `tab` key would only auto-complete but not also convert to a tag (like `rightKey` does).\r\n    },\r\n\r\n    classNames: {\r\n        namespace          : 'tagify',\r\n        mixMode            : 'tagify--mix',\r\n        selectMode         : 'tagify--select',\r\n        input              : 'tagify__input',\r\n        focus              : 'tagify--focus',\r\n        tagNoAnimation     : 'tagify--noAnim',\r\n        tagInvalid         : 'tagify--invalid',\r\n        tagNotAllowed      : 'tagify--notAllowed',\r\n        scopeLoading       : 'tagify--loading',\r\n        hasMaxTags         : 'tagify--hasMaxTags',\r\n        hasNoTags          : 'tagify--noTags',\r\n        empty              : 'tagify--empty',\r\n        inputInvalid       : 'tagify__input--invalid',\r\n        dropdown           : 'tagify__dropdown',\r\n        dropdownWrapper    : 'tagify__dropdown__wrapper',\r\n        dropdownHeader     : 'tagify__dropdown__header',\r\n        dropdownFooter     : 'tagify__dropdown__footer',\r\n        dropdownItem       : 'tagify__dropdown__item',\r\n        dropdownItemActive : 'tagify__dropdown__item--active',\r\n        dropdownItemHidden : 'tagify__dropdown__item--hidden',\r\n        dropdownInital     : 'tagify__dropdown--initial',\r\n        tag                : 'tagify__tag',\r\n        tagText            : 'tagify__tag-text',\r\n        tagX               : 'tagify__tag__removeBtn',\r\n        tagLoading         : 'tagify__tag--loading',\r\n        tagEditing         : 'tagify__tag--editable',\r\n        tagFlash           : 'tagify__tag--flash',\r\n        tagHide            : 'tagify__tag--hide',\r\n\r\n    },\r\n\r\n    dropdown: {\r\n        classname          : '',\r\n        enabled            : 2,      // minimum input characters to be typed for the suggestions dropdown to show\r\n        maxItems           : 10,\r\n        searchKeys         : [\"value\", \"searchBy\"],\r\n        fuzzySearch        : true,\r\n        caseSensitive      : false,\r\n        accentedSearch     : true,\r\n        includeSelectedTags: false,  // Should the suggestions list Include already-selected tags (after filtering)\r\n        escapeHTML         : true,   // escapes HTML entities in the suggestions' rendered text\r\n        highlightFirst     : true,  // highlights first-matched item in the list\r\n        closeOnSelect      : true,   // closes the dropdown after selecting an item, if `enabled:0` (which means always show dropdown)\r\n        clearOnSelect      : true,   // after selecting a suggetion, should the typed text input remain or be cleared\r\n        position           : 'all',  // 'manual' / 'text' / 'all'\r\n        appendTarget       : null    // defaults to document.body once DOM has been loaded\r\n    },\r\n\r\n    hooks: {\r\n        beforeRemoveTag: () => Promise.resolve(),\r\n        beforePaste: () => Promise.resolve(),\r\n        suggestionClick: () => Promise.resolve(),\r\n        beforeKeyDown: () => Promise.resolve(),\r\n    }\r\n}","import { isObject, escapeHTML, extend, unaccent } from './helpers'\n\n\n/**\n * Tagify's dropdown suggestions-related logic\n */\n\nexport default {\n    events : {\n        /**\n         * Events should only be binded when the dropdown is rendered and removed when isn't\n         * because there might be multiple Tagify instances on a certain page\n         * @param  {Boolean} bindUnbind [optional. true when wanting to unbind all the events]\n         */\n        binding( bindUnbind = true ){\n            // references to the \".bind()\" methods must be saved so they could be unbinded later\n            var _CB = this.dropdown.events.callbacks,\n                // callback-refs\n                _CBR = (this.listeners.dropdown = this.listeners.dropdown || {\n                    position          : this.dropdown.position.bind(this, null),\n                    onKeyDown         : _CB.onKeyDown.bind(this),\n                    onMouseOver       : _CB.onMouseOver.bind(this),\n                    onMouseLeave      : _CB.onMouseLeave.bind(this),\n                    onClick           : _CB.onClick.bind(this),\n                    onScroll          : _CB.onScroll.bind(this),\n                }),\n                action = bindUnbind ? 'addEventListener' : 'removeEventListener';\n\n            if( this.settings.dropdown.position != 'manual' ){\n                document[action]('scroll', _CBR.position, true)\n                window[action]('resize', _CBR.position)\n                window[action]('keydown', _CBR.onKeyDown)\n            }\n\n            this.DOM.dropdown[action]('mouseover', _CBR.onMouseOver)\n            this.DOM.dropdown[action]('mouseleave', _CBR.onMouseLeave)\n            this.DOM.dropdown[action]('mousedown', _CBR.onClick)\n            this.DOM.dropdown.content[action]('scroll', _CBR.onScroll)\n        },\n\n        callbacks : {\n            onKeyDown(e){\n                // ignore keys during IME composition\n                if( !this.state.hasFocus || this.state.composing )\n                    return\n\n                // get the \"active\" element, and if there was none (yet) active, use first child\n                var _s = this.settings,\n                    selectedElm = this.DOM.dropdown.querySelector(_s.classNames.dropdownItemActiveSelector),\n                    selectedElmData = this.dropdown.getSuggestionDataByNode(selectedElm),\n                    isMixMode = _s.mode == 'mix';\n\n                _s.hooks.beforeKeyDown(e, {tagify:this})\n                    .then(result => {\n                        switch( e.key ){\n                            case 'ArrowDown' :\n                            case 'ArrowUp' :\n                            case 'Down' :  // >IE11\n                            case 'Up' : {  // >IE11\n                                e.preventDefault()\n                                var dropdownItems = this.dropdown.getAllSuggestionsRefs(),\n                                    actionUp = e.key == 'ArrowUp' || e.key == 'Up';\n\n                                if( selectedElm ) {\n                                    selectedElm = this.dropdown.getNextOrPrevOption(selectedElm, !actionUp)\n                                }\n\n                                // if no element was found OR current item is not a \"real\" item, loop\n                                if( !selectedElm || !selectedElm.matches(_s.classNames.dropdownItemSelector) ){\n                                    selectedElm = dropdownItems[actionUp ? dropdownItems.length - 1 : 0];\n                                }\n\n                                this.dropdown.highlightOption(selectedElm, true)\n                                // selectedElm.scrollIntoView({inline: 'nearest', behavior: 'smooth'})\n                                break;\n                            }\n                            case 'Escape' :\n                            case 'Esc': // IE11\n                                this.dropdown.hide();\n                                break;\n\n                            case 'ArrowRight' :\n                                if( this.state.actions.ArrowLeft )\n                                    return\n                            case 'Tab' : {\n                                let shouldAutocompleteOnKey = !_s.autoComplete.rightKey || !_s.autoComplete.tabKey\n\n                                // in mix-mode, treat arrowRight like Enter key, so a tag will be created\n                                if( !isMixMode && selectedElm && shouldAutocompleteOnKey && !this.state.editing ){\n                                    e.preventDefault() // prevents blur so the autocomplete suggestion will not become a tag\n                                    var value = this.dropdown.getMappedValue(selectedElmData)\n\n                                    this.input.autocomplete.set.call(this, value)\n                                    return false\n                                }\n                                return true\n                            }\n                            case 'Enter' : {\n                                e.preventDefault()\n\n                                _s.hooks.suggestionClick(e, {tagify:this, tagData:selectedElmData, suggestionElm:selectedElm})\n                                    .then(() => {\n                                        if( selectedElm ){\n                                            this.dropdown.selectOption(selectedElm)\n                                            // highlight next option\n                                            selectedElm = this.dropdown.getNextOrPrevOption(selectedElm, !actionUp)\n                                            this.dropdown.highlightOption(selectedElm)\n                                            return\n                                        }\n                                        else\n                                            this.dropdown.hide()\n\n                                        if( !isMixMode )\n                                            this.addTags(this.state.inputText.trim(), true)\n                                    })\n                                    .catch(err => Tagify.logger.warn(err))\n\n                                break;\n                            }\n                            case 'Backspace' : {\n                                if( isMixMode || this.state.editing.scope ) return;\n\n                                const value = this.input.raw.call(this)\n\n                                if( value == \"\" || value.charCodeAt(0) == 8203 ){\n                                    if( _s.backspace === true )\n                                        this.removeTags()\n                                    else if( _s.backspace == 'edit' )\n                                        setTimeout(this.editTag.bind(this), 0)\n                                }\n                            }\n                        }\n                    })\n            },\n\n            onMouseOver(e){\n                var ddItem = e.target.closest(this.settings.classNames.dropdownItemSelector)\n                // event delegation check\n                this.dropdown.highlightOption(ddItem)\n            },\n\n            onMouseLeave(e){\n                // de-highlight any previously highlighted option\n                this.dropdown.highlightOption()\n            },\n\n            onClick(e){\n                if( e.button != 0 || e.target == this.DOM.dropdown || e.target == this.DOM.dropdown.content ) return; // allow only mouse left-clicks\n\n                var selectedElm = e.target.closest(this.settings.classNames.dropdownItemSelector),\n                    selectedElmData = this.dropdown.getSuggestionDataByNode(selectedElm)\n\n                // temporary set the \"actions\" state to indicate to the main \"blur\" event it shouldn't run\n                this.state.actions.selectOption = true;\n                setTimeout(()=> this.state.actions.selectOption = false, 50)\n\n                this.settings.hooks.suggestionClick(e, {tagify:this, tagData:selectedElmData, suggestionElm:selectedElm})\n                    .then(() => {\n                        if( selectedElm )\n                            this.dropdown.selectOption(selectedElm, e)\n                        else\n                            this.dropdown.hide()\n                    })\n                    .catch(err => Tagify.logger.warn(err))\n            },\n\n            onScroll(e){\n                var elm = e.target,\n                    pos = elm.scrollTop / (elm.scrollHeight - elm.parentNode.clientHeight) * 100;\n\n                this.trigger(\"dropdown:scroll\", {percentage:Math.round(pos)})\n            },\n        }\n    },\n\n    /**\n     * fill data into the suggestions list\n     * (mainly used to update the list when removing tags while the suggestions dropdown is visible, so they will be re-added to the list. not efficient)\n     */\n    refilter( value ){\n        value = value || this.state.dropdown.query || ''\n        this.suggestedListItems = this.dropdown.filterListItems(value)\n\n        this.dropdown.fill()\n\n        if( !this.suggestedListItems.length )\n            this.dropdown.hide()\n\n        this.trigger(\"dropdown:updated\", this.DOM.dropdown)\n    },\n\n    /**\n     * Given a suggestion-item, return the data associated with it\n   